        for (Object mock : mocks) {
            if (field.getType().isAssignableFrom(mock.getClass()) && mock != fieldInstance) {
                mockTypeMatches.add(mock);
            }
        }

        return next.filterCandidate(mockTypeMatches, field, fieldInstance);
    }
