     *
     * @param returnTypeGenericMetadata The metadata to use to create the new mock.
     * @return The mock
     */
    private Object recordDeepStubMock(InvocationOnMock invocation, InvocationContainerImpl container, GenericMetadataSupport returnTypeGenericMetadata) {
        Class<?> rawType = returnTypeGenericMetadata.rawType();
        CreationSettings settings = new CreationSettings();
        settings.setTypeToMock(rawType);
        settings.setExtraInterfaces(returnTypeGenericMetadata.extraInterfaces());
        settings.setSerializable(Serializable.class);

        final Object mock = org.mockito.Mockito.mock(rawType, this);

        container.addAnswer(new Answer<Object>() {
            public Object answer(InvocationOnMock invocation) throws Throwable {
                return mock;
            }
        }, false);

        return mock;
    }

    protected GenericMetadataSupport actualParameterizedType(Object mock) {
        CreationSettings mockSettings = (CreationSettings) new MockUtil().getMockHandler(mock).getMockSettings();
        return GenericMetadataSupport.inferFrom(mockSettings.getTypeToMock());
    }
}
