            printer.withChronology(withUTC()).printTo(sb, iCutoverMillis);
        }

        if (getMinimumDaysInFirstWeek() != 4) {
            sb.append(",mdfw=");
            sb.append(getMinimumDaysInFirstWeek());
        }
        sb.append(']');

        return sb.toString();
    }

    protected void assemble(Fields fields) {
